package com.example.battleshipgame.customview;
import android.content.Context;import android.graphics.*;import android.view.*;import com.example.battleshipgame.logic.*;
public class BattleshipBoardView extends View {private Board board;private boolean revealShips,enabled=true;private final Paint p=new Paint(1);private OnCellClick listener;public interface OnCellClick{void click(int row,int col);}public BattleshipBoardView(Context c){super(c);p.setStyle(Paint.Style.FILL);setPadding(8,8,8,8);setBackgroundColor(Color.rgb(8,32,53));}public void setBoard(Board b,boolean reveal){board=b;revealShips=reveal;invalidate();}public void setBoardEnabled(boolean value){enabled=value;setAlpha(value?1f:.55f);}public void setOnCellClick(OnCellClick l){listener=l;}protected void onDraw(Canvas c){super.onDraw(c);if(board==null)return;float cell=Math.min(getWidth(),getHeight())/(float)Board.SIZE;p.setColor(Color.rgb(31,99,128));c.drawRoundRect(0,0,cell*Board.SIZE,cell*Board.SIZE,16,16,p);for(int r=0;r<Board.SIZE;r++)for(int col=0;col<Board.SIZE;col++){Board.Cell state=board.get(r,col);int color=Color.rgb(13,62,94);if(state==Board.Cell.SHIP&&revealShips)color=Color.rgb(62,148,171);if(state==Board.Cell.MISS)color=Color.rgb(136,194,212);if(state==Board.Cell.HIT)color=Color.rgb(244,91,71);p.setColor(color);c.drawRoundRect(col*cell+2,r*cell+2,(col+1)*cell-2,(r+1)*cell-2,cell*.12f,cell*.12f,p);if(state==Board.Cell.MISS||state==Board.Cell.HIT){p.setColor(Color.WHITE);p.setTextSize(cell*.65f);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextAlign(Paint.Align.CENTER);c.drawText(state==Board.Cell.MISS?"•":"×",(col+.5f)*cell,(r+.72f)*cell,p);}}}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_UP&&enabled&&board!=null&&listener!=null){float cell=Math.min(getWidth(),getHeight())/(float)Board.SIZE;listener.click((int)(e.getY()/cell),(int)(e.getX()/cell));}return true;}}
